};

// --- HELPER COMPONENTS ---

const Card = ({ children, className = "" }) => (
    <div className={`bg-slate-900/80 backdrop-blur-md border border-slate-800 rounded-xl p-6 shadow-2xl ${className}`}>
        {children}
    </div>
);

const Button = ({ onClick, children, variant = 'primary', className = "", disabled=false }) => {
    const base = "px-6 py-3 rounded-lg font-mono font-bold uppercase tracking-widest transition-all duration-300 flex items-center justify-center gap-2";
    const styles = {
        primary: "bg-cyan-900/40 text-cyan-400 border border-cyan-500/50 hover:bg-cyan-500 hover:text-black hover:shadow-[0_0_20px_rgba(6,182,212,0.4)]",
        secondary: "bg-slate-800 text-slate-400 border border-slate-700 hover:bg-slate-700 hover:text-white",
        danger: "bg-red-900/20 text-red-500 border border-red-900/50 hover:bg-red-900/40",
        ghost: "bg-transparent text-slate-500 hover:text-cyan-400"
    };
    return (
        <button onClick={onClick} disabled={disabled} className={`${base} ${styles[variant]} ${disabled ? 'opacity-50 cursor-not-allowed' : ''} ${className}`}>
            {children}
        </button>
    );
};

const Badge = ({ children, color = 'cyan' }) => {
    const colors = {
        cyan: 'bg-cyan-900/30 text-cyan-400 border-cyan-500/30',
        purple: 'bg-purple-900/30 text-purple-400 border-purple-500/30',
        green: 'bg-green-900/30 text-green-400 border-green-500/30',
        yellow: 'bg-yellow-900/30 text-yellow-400 border-yellow-500/30',
        red: 'bg-red-900/30 text-red-400 border-red-500/30'
    };
    return (
        <span className={`px-2 py-0.5 rounded text-[10px] font-bold font-mono border ${colors[color]}`}>
