    );
};

const Avatar = ({ char }) => (
    <div className="w-10 h-10 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-xl">
        {char}
    </div>
);

// --- MAIN APP ---

export default function HALO_Net() {
    const [view, setView] = useState('login'); // login, dashboard, reading, codex, social
    const [user, setUser] = useState(null);
    const [query, setQuery] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [readingResult, setReadingResult] = useState(null);
    const [liveSearchData, setLiveSearchData] = useState(null);
    const [feed, setFeed] = useState(MOCK_DB.feed);

    // --- MOCK AUTH ---
    const handleLogin = (provider) => {
        setIsLoading(true);
        setTimeout(() => {
            setUser(MOCK_DB.user);
            setView('dashboard');
            setIsLoading(false);
        }, 1500);
    };

    // --- MOCK ENGINE ---
    const executeDivination = async () => {
        if(!query) return;
        setIsLoading(true);

        // 1. Simulate "Live Web Search"
        setTimeout(() => {
            setLiveSearchData({
                context: "Current astrological transit: Saturn retrograde. Global sentiment: Volatile.",
                keywords: ["Transformation", "Digital Currencies", "Solar Flares"]
            });
        }, 1000);

        // 2. Simulate Cloud Computation
        setTimeout(() => {
            const result = {
                id: 'read_' + Math.floor(Math.random() * 10000),
                query: query,
                vectors: {
                    d100: Math.floor(Math.random() * 100) + 1,
                    archetype: 'The Glitch Saint',
                    biome: 'The Fae Labyrinth',
                    rune: 'Dagaz (Breakthrough)',
                    element: 'Fire (Generating Earth)'
                },
                synthesis: `The system detects a high probability (${Math.floor(Math.random() * 100)}%) of success. The Glitch Saint disrupts the stagnant energy in the Fae Labyrinth. Dagaz indicates a sudden realization or dawn. Grounding this in the current volatile global sentiment, this suggests a pivot is necessary now.`,
                webContext: "Correlation found with recent solar flare activity affecting communications."
            };
            setReadingResult(result);

            // Add to feed automatically (Shared Divination)
            const newFeedItem = {
                id: result.id,
                user: user.name,
                avatar: user.avatar,
                type: 'Public Reading',
                query: result.query,
                result: `${result.vectors.archetype} + ${result.vectors.rune}`,
                synthesis: result.synthesis,
                time: 'Just now',
                likes: 0,
                comments: []
            };
            setFeed([newFeedItem, ...feed]);

            setIsLoading(false);
            setView('reading');
        }, 3000);
    };

    // --- SOCIAL ACTIONS ---
    const handleLike = (id) => {
        const updatedFeed = feed.map(item => {
            if (item.id === id) {
                return { ...item, likes: item.likes + 1 };
            }
            return item;
        });
        setFeed(updatedFeed);
    };

    // --- VIEWS ---

    const LoginView = () => (
        <div className="min-h-screen flex flex-col items-center justify-center relative overflow-hidden bg-black">
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(6,182,212,0.15),transparent_70%)] animate-pulse"></div>

            <Card className="w-full max-w-md z-10 border-cyan-500/30">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-cyan-900/20 rounded-full flex items-center justify-center mx-auto mb-4 border border-cyan-500 shadow-[0_0_30px_rgba(6,182,212,0.3)]">
                        <Globe className="w-8 h-8 text-cyan-400" />
                    </div>
                    <h1 className="text-4xl font-bold font-serif text-white tracking-widest mb-2">HALO<span className="text-cyan-400">.NET</span></h1>
                    <p className="text-xs font-mono text-slate-500 uppercase tracking-[0.3em]">Connected Divination Platform v6.1</p>
                </div>

                <div className="space-y-4">
                    <Button onClick={() => handleLogin('google')} className="w-full" variant="primary">
                        <Unlock className="w-4 h-4" /> Sign in with Google
                    </Button>
                    <Button onClick={() => handleLogin('anon')} className="w-full" variant="secondary">
                        <Users className="w-4 h-4" /> Guest Access
                    </Button>
                </div>

                <div className="mt-8 pt-6 border-t border-slate-800 text-center">
                    <p className="text-[10px] text-slate-600 font-mono">
                        SECURE CONNECTION // AWS HOSTED // ENCRYPTED
                    </p>
                </div>
            </Card>
        </div>
    );

    const DashboardView = () => (
        <div className="max-w-6xl mx-auto w-full pt-8 px-4">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 border-b border-slate-800 pb-4">
                <div>
                    <h2 className="text-3xl font-serif text-white">Welcome, {user.name}</h2>
                    <div className="flex gap-4 mt-2 text-xs font-mono text-slate-400">
                        <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-green-500"></div> ONLINE</span>
                        <span>COVEN: <span className="text-purple-400">{user.coven}</span></span>
                        <span>TOKENS: {user.tokens}</span>
                    </div>
                </div>
                <div className="flex gap-2 mt-4 md:mt-0">
                    <Button variant="ghost" onClick={() => setView('social')}><Users className="w-4 h-4"/> Coven</Button>
                    <Button variant="ghost" onClick={() => setView('codex')}><Database className="w-4 h-4"/> Codex</Button>
                    <Button variant="ghost" onClick={() => { setUser(null); setView('login'); }}><LogOut className="w-4 h-4"/></Button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                {/* Main Query Engine */}
                <div className="lg:col-span-2 space-y-6">
                    <Card className="relative overflow-hidden group border-cyan-500/30">
                        <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500 transition-all group-hover:w-full group-hover:opacity-10"></div>
                        <label className="block text-xs font-mono text-cyan-400 mb-4 uppercase tracking-widest flex justify-between">
                            <span>&gt;&gt; New Query Vector</span>
                            <span className="flex items-center gap-1 text-slate-500"><Wifi className="w-3 h-3"/> LIVE SEARCH ACTIVE</span>
                        </label>
                        <textarea 
                            value={query}
                            onChange={(e) => setQuery(e.target.value)}
                            className="w-full bg-black/50 border border-slate-700 rounded p-4 text-lg text-white font-mono focus:border-cyan-500 outline-none h-32 resize-none mb-4 placeholder-slate-700"
                            placeholder="What requires illumination?"
                        />
                        <div className="flex justify-between items-center">
                            <div className="text-xs text-slate-500 font-mono hidden md:block">
                                MODULES: <span className="text-white">DICE, TAROT, RUNES, WEB</span>
                            </div>
                            <Button onClick={executeDivination} disabled={!query}>
                                {isLoading ? 'Processing...' : 'Initiate Scan'}
                            </Button>
                        </div>
                    </Card>

                    {/* Compact Feed Preview */}
                    <div className="opacity-75 hover:opacity-100 transition-opacity">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Recent Coven Activity</h3>
                            <button onClick={() => setView('social')} className="text-xs text-cyan-500 hover:underline">View All</button>
                        </div>
                        <div className="space-y-2">
                            {feed.slice(0, 2).map(item => (
                                <div key={item.id} className="bg-slate-900 border border-slate-800 p-3 rounded flex justify-between items-center">
                                    <div className="flex items-center gap-3">
                                        <Avatar char={item.avatar} />
                                        <div>
                                            <div className="text-sm text-cyan-400 font-bold">{item.user}</div>
                                            <div className="text-xs text-slate-400">{item.type} • {item.result}</div>
                                        </div>
                                    </div>
                                    <div className="text-xs font-mono text-slate-600">{item.time}</div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Sidebar Stats */}
                <div className="space-y-6">
                    <Card className="border-purple-500/20">
                        <h3 className="text-xs font-bold text-purple-400 mb-4 uppercase tracking-widest">Global Sync</h3>
                        <div className="text-4xl font-mono text-white mb-2 font-bold flex items-center gap-2">
                            <Zap className="w-8 h-8 text-yellow-500" />
                            98.4%
                        </div>
                        <div className="text-xs text-slate-500 mb-4">Network resonance is high.</div>
                        <div className="h-1 w-full bg-slate-800 rounded overflow-hidden">
                            <div className="h-full bg-purple-500 w-[98%] animate-pulse"></div>
                        </div>
                    </Card>

                    <Card>
                        <h3 className="text-xs font-bold text-slate-400 mb-4 uppercase tracking-widest">Daily Wisdom</h3>
                        <div className="text-xl font-serif text-white mb-2">"The glitch is the guru."</div>
                        <div className="text-xs text-cyan-500 font-mono text-right">- GG</div>
                    </Card>
                </div>

            </div>
        </div>
    );

    const SocialView = () => (
        <div className="max-w-4xl mx-auto w-full pt-8 px-4">
             <div className="flex justify-between items-center mb-8 border-b border-slate-800 pb-4">
                <Button variant="ghost" onClick={() => setView('dashboard')}>← Dashboard</Button>
                <div className="flex items-center gap-2">
                    <h2 className="text-2xl font-serif text-white">The Coven</h2>
                    <Badge color="purple">{MOCK_DB.users.length} Adepts Online</Badge>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {/* Active Users */}
                <div className="lg:col-span-1 space-y-4">
                    <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Active Adepts</h3>
                    {MOCK_DB.users.map(u => (
                        <div key={u.id} className="flex items-center justify-between bg-slate-900/50 p-2 rounded border border-slate-800">
                            <span className="text-sm text-slate-300">{u.name}</span>
                            <div className={`w-2 h-2 rounded-full ${u.status === 'online' ? 'bg-green-500 shadow-[0_0_5px_#22c55e]' : 'bg-slate-600'}`}></div>
                        </div>
                    ))}
                </div>

                {/* The Feed */}
                <div className="lg:col-span-3 space-y-6">
                    {feed.map(item => (
                        <Card key={item.id} className="hover:border-cyan-500/30 transition-colors">
                            <div className="flex justify-between items-start mb-4">
                                <div className="flex items-center gap-3">
                                    <Avatar char={item.avatar} />
                                    <div>
                                        <div className="font-bold text-white">{item.user}</div>
                                        <div className="text-xs text-slate-500">{item.time} • <span className="text-cyan-500">{item.type}</span></div>
                                    </div>
                                </div>
                                <Button variant="ghost" className="p-0 h-auto"><Share2 className="w-4 h-4" /></Button>
                            </div>

                            <div className="mb-4 pl-14">
                                <div className="text-sm text-slate-400 italic mb-2">"{item.query}"</div>
                                <div className="p-3 bg-black/40 rounded border border-slate-800 mb-3">
                                    <div className="text-xs text-slate-500 mb-1">RESULT VECTOR</div>
                                    <div className="text-lg font-bold text-white font-mono">{item.result}</div>
                                </div>
                                <p className="text-slate-300 text-sm leading-relaxed">{item.synthesis}</p>
                            </div>

                            <div className="pl-14 flex items-center gap-6 text-slate-500 text-xs font-mono">
                                <button onClick={() => handleLike(item.id)} className="flex items-center gap-2 hover:text-red-400 transition-colors">
                                    <Heart className={`w-4 h-4 ${item.likes > 0 ? 'fill-red-500/20 text-red-500' : ''}`} /> 
                                    {item.likes} Resonance
                                </button>
                                <button className="flex items-center gap-2 hover:text-cyan-400 transition-colors">
                                    <MessageSquare className="w-4 h-4" /> 
                                    {item.comments.length} Interpretations
                                </button>
                            </div>

                            {/* Comments Section */}
                            {item.comments.length > 0 && (
                                <div className="mt-4 pl-14 space-y-2">
                                    {item.comments.map((comment, idx) => (
                                        <div key={idx} className="text-xs bg-slate-800/50 p-2 rounded">
                                            <span className="font-bold text-cyan-400">{comment.user}:</span> <span className="text-slate-400">{comment.text}</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </Card>
                    ))}
                </div>
            </div>
        </div>
    );

    const ReadingView = () => (
        <div className="max-w-4xl mx-auto w-full pt-12 px-4">
            <Button variant="ghost" onClick={() => setView('dashboard')} className="mb-6">← Return</Button>

            <Card className="border-cyan-500/50 shadow-[0_0_50px_rgba(6,182,212,0.1)]">
                <div className="flex justify-between items-start mb-8 border-b border-slate-800 pb-6">
                    <div>
                        <div className="flex gap-2 mb-2">
                            <Badge color="cyan">PROBABILITY: {readingResult.vectors.d100}%</Badge>
                            <Badge color="purple">{readingResult.vectors.archetype.toUpperCase()}</Badge>
                        </div>
                        <h2 className="text-3xl font-serif text-white">{readingResult.query}</h2>
                    </div>
                    <div className="text-right">
                        <div className="text-xs font-mono text-slate-500">ID: {readingResult.id}</div>
                        <div className="text-xs font-mono text-green-500">VERIFIED</div>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-8">
                    <div className="p-4 bg-black/40 rounded border border-slate-800">
                        <div className="text-xs text-slate-500 mb-1">BIOME</div>
                        <div className="text-lg text-yellow-500 font-bold">{readingResult.vectors.biome}</div>
                    </div>
                    <div className="p-4 bg-black/40 rounded border border-slate-800">
                        <div className="text-xs text-slate-500 mb-1">RUNE</div>
                        <div className="text-lg text-white font-mono">{readingResult.vectors.rune}</div>
                    </div>
                    <div className="p-4 bg-black/40 rounded border border-slate-800">
                        <div className="text-xs text-slate-500 mb-1">ELEMENT</div>
                        <div className="text-lg text-green-500">{readingResult.vectors.element}</div>
                    </div>
                </div>

                <div className="prose prose-invert max-w-none mb-8">
                    <h3 className="text-cyan-400 font-mono text-sm uppercase">Synthesis Output</h3>
                    <p className="text-lg text-slate-300 leading-relaxed">
                        {readingResult.synthesis}
                    </p>
                </div>

                {liveSearchData && (
                    <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded mb-8">
                        <div className="flex items-center gap-2 text-blue-400 text-xs font-bold mb-2">
                            <Globe className="w-3 h-3" /> LIVE WEB CONTEXT
                        </div>
                        <p className="text-sm text-blue-200">{readingResult.webContext}</p>
                    </div>
                )}

                <div className="flex justify-end gap-4 border-t border-slate-800 pt-6">
                    <Button variant="secondary" onClick={() => setView('social')}><Share2 className="w-4 h-4" /> View in Coven</Button>
                    <Button variant="secondary"><Database className="w-4 h-4" /> Index Result</Button>
                </div>
            </Card>
        </div>
    );

    const CodexView = () => (
        <div className="max-w-4xl mx-auto w-full pt-12 px-4">
            <div className="flex justify-between items-center mb-6">
                <Button variant="ghost" onClick={() => setView('dashboard')}>← Dashboard</Button>
                <div className="relative">
                    <input type="text" placeholder="Search Symbols..." className="bg-slate-900 border border-slate-700 rounded px-4 py-2 text-sm text-white w-64 focus:border-cyan-500 outline-none" />
                    <Search className="w-4 h-4 text-slate-500 absolute right-3 top-2.5" />
                </div>
            </div>

            <h2 className="text-3xl font-serif text-white mb-6">The Living Codex</h2>

            <div className="grid gap-4">
                {Object.entries(MOCK_DB.codex.runes).map(([key, data]) => (
                    <div key={key} className="bg-slate-900/50 p-6 rounded border border-slate-800 hover:border-cyan-500/30 transition-colors">
                        <div className="flex justify-between items-start mb-2">
                            <h3 className="text-xl font-bold text-white">{key}</h3>
                            <Badge color="cyan">RUNE</Badge>
                        </div>
                        <p className="text-slate-400 mb-4">{data.mean}</p>
                        <div className="bg-black/30 p-3 rounded text-xs font-mono text-slate-500">
                            <strong>Community Notes:</strong>
                            <ul className="list-disc pl-4 mt-1 space-y-1">
                                {data.community_notes.map((note, i) => <li key={i}>{note}</li>)}
                            </ul>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );

    // --- RENDERER ---
    return (
        <div className="min-h-screen bg-[#020408] text-slate-200 font-sans selection:bg-cyan-500 selection:text-black">
            {view === 'login' && <LoginView />}

            {isLoading && view !== 'login' && (
                <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur flex flex-col items-center justify-center">
                    <div className="w-16 h-16 border-4 border-cyan-900 border-t-cyan-500 rounded-full animate-spin mb-4"></div>
                    <div className="font-mono text-cyan-500 text-sm animate-pulse">ACCESSING CLOUD NODES...</div>
                </div>
            )}

            {!isLoading && view === 'dashboard' && <DashboardView />}
            {!isLoading && view === 'reading' && <ReadingView />}
            {!isLoading && view === 'codex' && <CodexView />}
            {!isLoading && view === 'social' && <SocialView />}
        </div>
    );
}


PROJECT DESCRIPTION AND PLAN:

# HALO Net: The Connected Divination Platform (v6.1)

## Project Overview

HALO Net (Hierophant-Aspect Labyrinthine Oracle Network) is a SaaS-architected, React-based web application designed to be a "techno-magical" ecosystem for divination, self-reflection, and collaborative myth-making. It evolves the user's original concept of a personal "Grimoire" and "Oracle" into a scalable, social platform.

The core philosophy is "Chaos Engineering for the Soul"—using randomness (dice, runes, tarot) combined with specific user-defined archetypes to generate meaningful narratives.

## Core Features (v6.1)

### 1. The Chaos Engine (Divination Core)

This is the heart of the application. It uses a multi-vector probability system to generate readings.

* **Vectors:**
* **Dice (D4-D100):** Determines Probability (D100), Archetype (D20), Biome/Setting (D12), and Narrative Voice (D4).
* **Runes (Elder Futhark):** A 3-rune "Norns" spread (Past/Present/Future) with reversal logic (50% chance).
* **Elements (Wu Xing/Pokemon):** Determines the elemental cycle (Generating vs. Overcoming) to add flavor to the reading (e.g., "Fire generating Earth").


* **Synthesis:** An algorithmic sentence builder that takes these disparate inputs and constructs a coherent narrative sentence (e.g., "*Solaris speaks from the Godmind Core regarding the Axis Seraph...*").

### 2. Live Web Context (Simulated)

* **Grounding:** The system "fetches" (simulated) live data like current astrological transits or global sentiment keywords to "ground" the esoteric reading in the real world.

### 3. The "Coven" (Social Layer)

* **Feed:** A real-time activity stream showing readings from other users.
* **Interaction:** Users can "Like" (Resonate) with readings or leave comments to offer their own interpretations.
* **Status:** Users have statuses (Online/Offline) and can see who is active in the "Circle."

### 4. The Living Codex (Knowledge Base)

* **Database:** A searchable library of all symbols (Runes, Tarot, Archetypes) used in the system.
* **Community Notes:** A wiki-like feature where users can append new meanings to symbols based on collective experience (e.g., "Fehu signifies crypto gains in 2025").

### 5. User System (Cloud-Ready)

* **Auth:** Supports Google Sign-In and Anonymous Guest access.
* **Profile:** Tracks user stats (Tokens, Covenant affiliation).
* **Persistence:** Architected to store user history and preferences in a cloud database (Firebase/AWS).

